/**
 * Mechanism templates: KET files in ./mechanisms, described by ./index.json.
 * Generated by templates/build_templates.py (see templates/README.md).
 */

export interface MechanismTemplate {
  id: string;
  file: string;
  title: string;
  category: 'organic' | 'inorganic' | 'biochemistry';
  description: string;
  electrons: '1e' | '2e';
  reference: string;
  ket: string;
}

const indexModules = import.meta.glob<Omit<MechanismTemplate, 'ket'>[]>('./index.json', { eager: true, import: 'default' });
const ketModules = import.meta.glob<string>('./mechanisms/*.ket', { eager: true, query: '?raw', import: 'default' });

export const TEMPLATES: MechanismTemplate[] = (Object.values(indexModules)[0] ?? [])
  .map((t) => ({ ...t, ket: ketModules[`./${t.file}`] ?? '' }))
  .filter((t) => t.ket);

export const CATEGORY_LABEL: Record<MechanismTemplate['category'], string> = {
  organic: 'Organic',
  inorganic: 'Inorganic',
  biochemistry: 'Biochemistry',
};
